insert into evidence.sources(source_key,organisation_name,source_name,source_type,canonical_url,country_code,active)
select j->>'source_key',j->>'organisation_name',j->>'source_name',j->>'source_type',
       j->>'canonical_url','AU',true
from _nursing_source_rows_1
on conflict (source_key) do update
set organisation_name=excluded.organisation_name,
    source_name=excluded.source_name,
    source_type=excluded.source_type,
    canonical_url=excluded.canonical_url,
    country_code='AU',
    active=true,
    updated_at=now();

insert into evidence.source_snapshots(
  source_id,source_url,content_sha256,published_at,data_as_of,retrieved_at,
  snapshot_status,metadata
)
select s.id,j->>'canonical_url',j->>'row_hash',
       nullif(j->>'published_at','')::date,
       nullif(j->>'data_as_of','')::date,
       coalesce(nullif(j->>'retrieved_at','')::timestamptz,now()),
       j->>'snapshot_status',
       jsonb_build_object(
         'source_register','Nursing_Source_Register_v0.7_Release_Gap_Closure.xlsx',
         'record_id',j->>'record_id',
         'source_register_version','v0.7'
       )
from _nursing_source_rows_1
join evidence.sources s on s.source_key=j->>'source_key'
on conflict do nothing;

insert into evidence.metric_observations(
  metric_key,scope_type,scope_id,value,unit,source_snapshot_id,evidence_kind,
  confidence,methodology,assumptions,review_status,reviewed_at,reviewer_note
)
select j->>'metric_key','source_register_record',j->>'record_id',j->'value',
       nullif(j->>'unit',''),
       ss.id,j->>'evidence_kind',j->>'confidence',nullif(j->>'methodology',''),
       jsonb_build_object(
         'source_register_version','v0.7',
         'record_id',j->>'record_id',
         'verification_status',j->'full_record'->>'Verification Status',
         'use_status',j->'full_record'->>'Use Status',
         'calculation_link',j->'full_record'->>'Calculation Link',
         'assumption_id',j->'full_record'->>'Assumption ID'
       ),
       j->>'review_status',
       nullif(j->>'reviewed_at','')::timestamptz,
       nullif(j->>'reviewer_note','')
from _nursing_source_rows_1
join evidence.sources s on s.source_key=j->>'source_key'
join evidence.source_snapshots ss on ss.source_id=s.id and ss.content_sha256=j->>'row_hash'
on conflict (scope_id,source_snapshot_id,metric_key)
  where scope_type='source_register_record'
do update set
  value=excluded.value,
  unit=excluded.unit,
  evidence_kind=excluded.evidence_kind,
  confidence=excluded.confidence,
  methodology=excluded.methodology,
  assumptions=excluded.assumptions,
  review_status=excluded.review_status,
  reviewed_at=excluded.reviewed_at,
  reviewer_note=excluded.reviewer_note,
  updated_at=now();

insert into evidence.source_register_records(
  record_id,report_key,metric_observation_id,source_snapshot_id,
  verification_status,use_status,source_quality_grade,archived_copy,full_record
)
select j->>'record_id','au-nursing-roi-focus-2026-v1',mo.id,ss.id,
       j->'full_record'->>'Verification Status',
       j->'full_record'->>'Use Status',
       j->'full_record'->>'Source Quality Grade',
       j->'full_record'->>'Archived Copy',
       j->'full_record'
from _nursing_source_rows_1
join evidence.sources s on s.source_key=j->>'source_key'
join evidence.source_snapshots ss on ss.source_id=s.id and ss.content_sha256=j->>'row_hash'
join evidence.metric_observations mo
  on mo.scope_type='source_register_record'
 and mo.scope_id=j->>'record_id'
 and mo.source_snapshot_id=ss.id
on conflict (record_id) do update
set metric_observation_id=excluded.metric_observation_id,
    source_snapshot_id=excluded.source_snapshot_id,
    verification_status=excluded.verification_status,
    use_status=excluded.use_status,
    source_quality_grade=excluded.source_quality_grade,
    archived_copy=excluded.archived_copy,
    full_record=excluded.full_record,
    updated_at=now();

insert into evidence.claims(
  claim_key,claim_text,locale,claim_type,materiality,scope_type,scope_id,
  publication_status,valid_from
)
select 'nursing-v1:'||lower(j->>'record_id'),j->>'claim_text','en','fact','material',
       'source_register_record',j->>'record_id',j->>'publication_status',
       nullif(j->>'published_at','')::date
from _nursing_source_rows_1
on conflict (claim_key) do update
set claim_text=excluded.claim_text,
    publication_status=excluded.publication_status,
    valid_from=excluded.valid_from,
    updated_at=now();

insert into evidence.claim_evidence(claim_id,metric_observation_id,support_role)
select c.id,srr.metric_observation_id,
       case when srr.use_status='Approved for Use' then 'primary'
            when srr.use_status='Superseded' then 'limitation'
            else 'secondary' end
from _nursing_source_rows_1 r
join evidence.claims c on c.claim_key='nursing-v1:'||lower(r.j->>'record_id')
join evidence.source_register_records srr on srr.record_id=r.j->>'record_id'
on conflict (claim_id,metric_observation_id) do update set support_role=excluded.support_role;
